		{name: "encoded surrogate", input: "s = \"\xed\xa0\x80\"\n"},
		{name: "beyond U+10FFFF", input: "s = \"\xf4\x90\x80\x80\"\n"},
		{name: "invalid byte in comment", input: "# \xff\ns = \"v\"\n"},
